      honestL2: 'A cloud solution. There is no telemetry, centralized dashboards or native mobile apps.',
      honestL3: 'A mass automatic configuration tool. Orchestration exists, but it is opt-in and by plan.',
      honestL4: 'A universal router solution. It is tested on OpenWrt / GL.iNet; other firmwares would need adaptation.',
