      "decisionsLead": "NetPulse n’est pas un produit marketing : c’est un outil personnel construit pour résoudre de vrais problèmes. Voici les décisions qui suscitent le plus de questions.",
      "decOpenwrtTitle": "Pourquoi OpenWrt / GL.iNet ?",
      "decOpenwrtP": "NetPulse est né d’un réseau domestique avec quatre routeurs : un GL.iNet Flint 2 comme gateway et trois Xiaomi AX6 d’occasion. OpenWrt permet de flasher, d’inspecter et de contrôler le matériel. Sans cela, impossible de lire la FDB, iwinfo ou les événements iw qui alimentent l’app.",
